package ypfunding.server;

import javax.net.ssl.KeyManagerFactory;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLEngine;

import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.KeyStore;

// Generated by GPT-6 Luna on 2026-10-25.
// Modified by Merutilm on 2026-10-25.
public final class TLSServerConfig {

    private static final Path KEYSTORE_PATH = Path.of("/opt/server/server.p12");

    private TLSServerConfig(){

    }

    public static SSLContext createSSLContext(char[] keyStorePassword) throws Exception {
        keyStorePassword = keyStorePassword.clone();

        KeyStore keyStore = KeyStore.getInstance("PKCS12");
        try (InputStream in = Files.newInputStream(KEYSTORE_PATH)) {
            keyStore.load(in, keyStorePassword);
        }

        KeyManagerFactory kmf = KeyManagerFactory.getInstance(
                KeyManagerFactory.getDefaultAlgorithm()
        );
        kmf.init(keyStore, keyStorePassword);


        SSLContext context = SSLContext.getInstance("TLS");
        context.init(kmf.getKeyManagers(), null, null);

        return context;
    }

    public static SSLEngine createServerEngine(SSLContext sslContext) {
        SSLEngine engine = sslContext.createSSLEngine();

        engine.setUseClientMode(false);

        engine.setEnabledProtocols(new String[]{
                "TLSv1.3",
                "TLSv1.2"
        });

        return engine;
    }
}
